(function(root){'use strict';const base=root.PaisGuide,ageMap={"u3m":"Se o bebê passou a reagir menos à sua voz ou aos sons de casa, avise o pediatra. Não faça barulhos fortes para testar a audição.","3a5m":"Observe se o bebê ainda reage à sua voz e aos sons que costumava notar. Se ele passou a responder menos, conte ao pediatra quando percebeu a mudança.","6a11m":"Se o bebê deixou de procurar com os olhos ou com a cabeça um som conhecido ao qual antes respondia, avise a equipe. Se isso aconteceu de repente, procure pronto atendimento hoje.","1a":"Se a criança deixou de responder à sua voz ou a pedidos simples que antes entendia, peça uma avaliação da audição.","2a5":"Avise a equipe se a criança passou a pedir que repitam o que foi dito ou se tem dificuldade para entender conversas que antes acompanhava.","6a11":"Se está difícil ouvir em sala de aula, converse com o professor e peça que a criança se sente perto de quem fala, longe de fontes de ruído.","12a17":"Peça ao adolescente que descreva quando a audição mudou e se foi em um ouvido ou nos dois. Mesmo sem dor, uma queda súbita exige pronto atendimento hoje.","unknown":"Conte à equipe quando a audição mudou e se foi em um ouvido ou nos dois. Se a mudança foi de repente, procure pronto atendimento hoje."}, old="Perda auditiva súbita ou tontura intensa não deve ser tratada como simples entupimento. Procure avaliação no mesmo dia, mesmo sem dor; não espere a consulta de rotina.",updated="Se a criança passou a ouvir menos de repente, em um ou nos dois ouvidos, ou apresenta tontura intensa, procure pronto atendimento hoje, mesmo sem dor. Não espere a consulta marcada nem atribua isso a ouvido tampado.";
root.PaisGuide={...base,build(p={}){const r=base.build(p);if(!r?.ok||r.mode!=='guidance'||r.topic!=='bjhr_tuba')return r;
const note=ageMap[p.age||'unknown'];if(!note)return r;
let text=r.text;const sections=r.sections.map(s=>{if(s.id==='home'){const a=s.items[0];text=text.replace(a,a+'\n• '+note);return {...s,items:[...s.items,note]};}
if(s.id==='urgent'){const title=s.title.replace('MUDÁNÇA','MUDANÇA');text=text.replace(s.title,title).replace(old,updated);return {...s,title,items:s.items.map(t=>t.replace(old,updated))};}return s;});
return {...r,sections,text};}};})(window);
